```go
type Sample struct {
    X, Y, Z float64
    Payload [64]byte
}

func Energy(samples []Sample) float64 {
    var total float64
    for i := range samples {
        s := &samples[i]
        total += s.X*s.X + s.Y*s.Y + s.Z*s.Z
    }
    return total
}
